def line_rows(ws_values, ws_formulas):
    """Line-item rows keyed by the Jira key in column A (exactly OPS-<n>, unquoted). Also
    returns the raw text of any quoted column-A key so the failure can say so."""
    rows, quoted = {}, {}
    for row in ws_values.iter_rows(min_row=1, max_col=1):
        key = text_of(row[0].value)
        if not key:
            continue
        if re.fullmatch(r'OPS-\d+', key):
            rows[key] = [cell_pair(ws_values, ws_formulas, row[0].row, c) for c in range(1, 9)]
        elif is_quoted(key):
