def check_line(jira_key, cells, exp_date, exp_merchant, exp_amount, exp_category,
               exp_approved, exp_denied, tol_amount, tol_approved, tol_denied):
    issues = []
    p = f'{jira_key}: '
    _, (date_v, date_f), (merch_v, merch_f), (amt_v, amt_f), (cat_v, cat_f), \
        (appr_v, appr_f), (den_v, den_f), _ = cells
    if is_quoted(date_v):
        issues.append(quoted_msg(p, 'date', date_v))
    elif not date_matches(date_v, exp_date):
        issues.append(f'{p}date expected "{exp_date}", got "{shown(date_v, date_f)}"')
    if is_quoted(merch_v):
        issues.append(quoted_msg(p, 'merchant', merch_v))
    else:
        am, em = norm(merch_v), exp_merchant.lower()
        if not am or (em not in am and am not in em):
            issues.append(f'{p}merchant expected "{exp_merchant}", got "{shown(merch_v, merch_f)}"')
    amt = parse_amount(amt_v)
    if amt is None or abs(amt - exp_amount) > tol_amount:
        issues.append(f'{p}amount expected {exp_amount}, got "{shown(amt_v, amt_f)}"')
    if is_quoted(cat_v):
        issues.append(quoted_msg(p, 'category', cat_v))
    else:
        ac, ec = norm(cat_v), exp_category.lower()
        if not ac or (ec not in ac and ac not in ec):
            issues.append(f'{p}category expected "{exp_category}", got "{shown(cat_v, cat_f)}"')
