    if appr is None or abs(appr - exp_approved) > tol_approved:
        issues.append(f'{p}approved expected {exp_approved}, got "{shown(appr_v, appr_f)}"')
    if is_quoted(den_v):
        issues.append(quoted_msg(p, 'denied amount', den_v))
    else:
        den = parse_amount(den_v)
        if den is None:
            den = 0.0  # blank, '-', etc. mean nothing denied
        if abs(den - exp_denied) > tol_denied:
