def summary_entries(ws_values, ws_formulas):
    """(label, value, formula) triples below the 'Report Summary' marker in column A, or None."""
    start = None
    for row in ws_values.iter_rows(min_row=1, max_col=1):
        a = row[0].value
        if a is None or is_quoted(a):
            continue
        if 'report summary' in norm(a) or re.sub(r'\s+', '', norm(a)) == 'reportsummary':
            start = row[0].row
            break
