def find_label(entries, *candidates):
    """First unquoted label containing one of the candidates (tried in order), as
    (label, value, formula); None if absent."""
    for cand in candidates:
        for label, value, formula in entries:
            if not is_quoted(label) and cand in norm(label):
                return label, value, formula
    return None


def quoted_label(entries, *candidates):
    for cand in candidates:
        for label, _, _ in entries:
            if is_quoted(label) and cand in norm(label):
                return label
    return None


def check_summary(entries, jira_key, total_approved, tol_approved, total_denied, tol_denied,
                  status_ok, status_display, comment):
    failures = []

    def lookup(field, *cands):
        hit = find_label(entries, *cands)
        if hit is None:
            q = quoted_label(entries, *cands)
            failures.append(f'{field}: label {q!r} is quoted; quoted text is not accepted' if q
                            else f'{field}: no label found in Report Summary')
        return hit

    hit = lookup('Jira Key', 'jira key', 'jirakey', 'jira')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Jira Key', v))
        elif norm(v) != jira_key.lower():
            failures.append(f'Jira Key expected {jira_key}, got "{shown(v, f)}"')
    hit = lookup('Total Approved', 'total approved', 'totalapproved', 'approved total')
    if hit:
        _, v, f = hit
        ta = parse_amount(v)
        if ta is None or abs(ta - total_approved) > tol_approved:
            failures.append(f'Total Approved expected {total_approved} (±{tol_approved}), got "{shown(v, f)}"')
    hit = lookup('Total Denied', 'total denied', 'totaldenied', 'denied total')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Total Denied', v))
        else:
            td = parse_amount(v)
            if td is None:
                td = 0.0  # blank means nothing denied
            if abs(td - total_denied) > tol_denied:
                failures.append(f'Total Denied expected {total_denied}, got "{shown(v, f)}"')
    hit = lookup('Final Status', 'final status', 'finalstatus', 'status')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Final Status', v))
        elif not status_ok(norm(v)):
            failures.append(f'Final Status expected "{status_display}", got "{shown(v, f)}"')
    hit = lookup('Manager Notified', 'manager notified', 'managernotified', 'notified')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Manager Notified', v))
        elif norm(v) not in ('n', 'no'):
            failures.append(f'Manager Notified expected "N", got "{shown(v, f)}"')
    hit = lookup('Comments', 'comment')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Comment', v))
        else:
            cv, ce = norm(v), comment.lower()
            if cv != ce and ce not in cv:
                failures.append(f'Comment expected "{comment}", got "{shown(v, f)}"')
    return failures


def verify(workspace_path, external_services_path=None):
    ws, wsf, err = open_sheets(workspace_path, 'amina', 'hassan', 'Amina Hassan')
    if err:
        return err
    entries = summary_entries(ws, wsf)
    if entries is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No "Report Summary" section found in Amina Hassan sheet'}
    failures = check_summary(
        entries, jira_key='OPS-18', total_approved=4240.96, tol_approved=0.05,
        total_denied=0.0, tol_denied=0.05,
        status_ok=lambda fs: 'approved' in fs and 'partial' not in fs and 'denied' not in fs,
        status_display='Approved', comment='T&E review complete. All expenses approved.')
    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': 'Amina Hassan summary issues: ' + '; '.join(failures)}
    return {'pass': True, 'score': 1.0,
            'feedback': 'Amina Hassan Report Summary section verified: Jira Key OPS-18, Total Approved 4240.96, '
                        'Total Denied 0, Final Status Approved, Manager Notified N, correct comment'}

from pathlib import Path
import re
import datetime
import openpyxl

# Text cells that start or end with a quote character are never accepted: the SOP and the
# task instructions spell these values out verbatim, without quotes.
QUOTE_CHARS = '"\'`‘’‚‛“”„‟«»‹›'
DASH_CHARS = '‐‑‒–—―−'
MONTHS = {
    'jan': 1, 'january': 1, 'feb': 2, 'february': 2, 'mar': 3, 'march': 3,
    'apr': 4, 'april': 4, 'may': 5, 'jun': 6, 'june': 6, 'jul': 7, 'july': 7,
    'aug': 8, 'august': 8, 'sep': 9, 'sept': 9, 'september': 9, 'oct': 10,
    'october': 10, 'nov': 11, 'november': 11, 'dec': 12, 'december': 12,
}


def text_of(val):
    return '' if val is None else str(val).strip()


def norm(val):
    return text_of(val).lower()


def is_quoted(val):
    s = text_of(val)
    return bool(s) and (s[0] in QUOTE_CHARS or s[-1] in QUOTE_CHARS)


def quoted_msg(prefix, field, val):
    return f'{prefix}{field} {text_of(val)!r} is quoted; quoted values are not accepted'


def parse_amount(val):
    if val is None or isinstance(val, bool):
        return None
    if isinstance(val, (int, float)):
        return float(val)
    s = text_of(val)
    if is_quoted(s):
        return None
    s = s.replace('$', '').replace(',', '').replace(' ', '')
    try:
        return float(s)
    except ValueError:
        return None


def shown(value, formula):
    """Cell as reported in feedback; flags formulas whose result was never saved."""
    if value is None and isinstance(formula, str) and formula.startswith('='):
        return f'formula {formula} with no cached value (save the workbook with computed values)'
    return 'None' if value is None else str(value)


def _date(y, m, d):
    y = int(y)
    if y < 100:
        y += 2000
    try:
        return datetime.date(y, int(m), int(d))
    except ValueError:
        return None


def extract_dates(val):
    """All calendar dates in a cell, in order of appearance.

    Accepts date/datetime cells, M/D/YYYY, MM/DD/YYYY, M/D/YY, M-D-YYYY, YYYY-MM-DD
    (optionally followed by a time), 'May 5, 2026', '5 May 2026', an optional weekday
    prefix, and compact ranges such as 'May 5-8, 2026' or 'May 5 - May 8, 2026'.
    Any dash-like glyph counts as a dash.
    """
    if isinstance(val, datetime.datetime):
        return [val.date()]
    if isinstance(val, datetime.date):
        return [val]
    s = text_of(val).translate({ord(c): '-' for c in DASH_CHARS})
    found = []

    def take(match, *dates):
        nonlocal s
        if any(d is None for d in dates):
            return
        found.extend((match.start() + i, d) for i, d in enumerate(dates))
        s = s[:match.start()] + ' ' * (match.end() - match.start()) + s[match.end():]

    MON = r'([A-Za-z]{3,9})\.?'
    ORD = r'(?:st|nd|rd|th)?'
    SEP = r'\s*(?:-|to|through|thru)\s*'
    for m in list(re.finditer(r'\b' + MON + r'\s+(\d{1,2})' + ORD + SEP + MON + r'\s+(\d{1,2})' + ORD + r',?\s+(\d{4})\b', s)):
        m1, m2 = MONTHS.get(m.group(1).lower()), MONTHS.get(m.group(3).lower())
        if m1 and m2:
            take(m, _date(m.group(5), m1, m.group(2)), _date(m.group(5), m2, m.group(4)))
    for m in list(re.finditer(r'\b' + MON + r'\s+(\d{1,2})' + ORD + SEP + r'(\d{1,2})' + ORD + r',?\s+(\d{4})\b', s)):
        mo = MONTHS.get(m.group(1).lower())
        if mo:
            take(m, _date(m.group(4), mo, m.group(2)), _date(m.group(4), mo, m.group(3)))
    for m in list(re.finditer(r'\b' + MON + r'\s+(\d{1,2})' + ORD + r',?\s+(\d{4})\b', s)):
        mo = MONTHS.get(m.group(1).lower())
        if mo:
            take(m, _date(m.group(3), mo, m.group(2)))
    for m in list(re.finditer(r'\b(\d{1,2})' + ORD + r'\s+' + MON + r',?\s+(\d{4})\b', s)):
        mo = MONTHS.get(m.group(2).lower())
        if mo:
            take(m, _date(m.group(3), mo, m.group(1)))
    for m in list(re.finditer(r'(?<!\d)(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?!\d)', s)):
        take(m, _date(m.group(1), m.group(2), m.group(3)))
    for m in list(re.finditer(r'(?<!\d)(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})(?!\d)', s)):
        take(m, _date(m.group(3), m.group(1), m.group(2)))
    found.sort(key=lambda item: item[0])
    return [d for _, d in found]


def date_matches(actual, expected):
    """expected is 'M/D/YYYY' or 'M/D/YYYY - M/D/YYYY'. A single date must be the only date in
    the cell. A range is matched by both endpoints in order or, as before, by a single date
    equal to either endpoint."""
    if is_quoted(actual):
        return False
    exp = extract_dates(expected)
    act = extract_dates(actual)
    if not act:
        return False
    if len(exp) == 1:
        return act == exp
    return act == exp or (len(act) == 1 and act[0] in exp)


