from pathlib import Path
import openpyxl

def normalize_str(s):
    return str(s or '').strip().lower()

def verify(workspace_path, external_services_path=None):
    xlsx_path = Path(workspace_path) / 'expense_reports.xlsx'
    if not xlsx_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'expense_reports.xlsx not found'}
    try:
        wb = openpyxl.load_workbook(xlsx_path)
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to open: {e}'}
    if 'Leila Rahimi' not in wb.sheetnames:
        return {'pass': False, 'score': 0.0, 'feedback': 'Sheet "Leila Rahimi" not found'}
    ws = wb['Leila Rahimi']
    target_key = 'OPS-50'
    denial_reason = None
    for row in ws.iter_rows(min_row=2, values_only=True):
        if row[0] and str(row[0]).strip() == target_key:
            denial_reason = str(row[7] or '').strip() if len(row) > 7 else ''
            break
    if denial_reason is None:
        return {'pass': False, 'score': 0.0, 'feedback': f'Row {target_key} not found in Leila Rahimi sheet'}
    if not denial_reason:
        return {'pass': False, 'score': 0.0, 'feedback': f'Row {target_key} has empty Denial Reason but should explain excess tickets'}
    dr_lower = denial_reason.lower()
    failures = []
    # Must reference 8 tickets purchased
    if '8' not in dr_lower:
        failures.append('Denial reason does not mention 8 tickets purchased')
    # Must reference 5 attendees (or 2 staff + 3 clients)
    has_five = '5' in dr_lower
    has_2staff_3clients = ('2' in dr_lower and '3' in dr_lower) or ('staff' in dr_lower and 'client' in dr_lower)
    if not (has_five or has_2staff_3clients):
        failures.append('Denial reason does not reference 5 valid attendees (2 staff + 3 clients)')
    # Must reference 3 denied tickets
    if '3' not in dr_lower:
        failures.append('Denial reason does not mention 3 tickets denied')
    if failures:
        # SOP 6.2 step 6c also permits citing the directly violated policy
        # instead of the literal counts: OPS-50 violates the client
        # entertainment rule (units purchased beyond the listed attendee
        # count are denied at the per-unit rate), so accept a reason that
        # connects the excess tickets/units to the listed attendees.
        import re
        has_unit = re.search(r'\b(tickets?|units?|covers?|admissions?|players?)\b', dr_lower)
        has_excess = re.search(r'\b(exceed\w*|excess\w*|beyond|extra|more|over|unlisted|cap|capped)\b', dr_lower)
        has_attendee = re.search(r'\b(attendee\w*|participant\w*|staff|clients?|listed|per[\s-]?(?:unit|person|ticket|head))\b', dr_lower)
        if has_unit and has_excess and has_attendee:
            return {'pass': True, 'score': 1.0, 'feedback': f'Lock & Lantern Escape Room denial reason cites the violated client-entertainment policy (tickets/units beyond the listed attendees, SOP 6.2 step 6c). Reason: "{denial_reason}"'}
    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Lock & Lantern denial reason issues: {failures}. Actual reason: "{denial_reason}"'}
    return {'pass': True, 'score': 1.0, 'feedback': f'Lock & Lantern Escape Room denial reason correctly references 8 tickets, 5 valid attendees, and 3 denied tickets. Reason: "{denial_reason}"'}

from pathlib import Path
import re
import datetime
import openpyxl

# Text cells that start or end with a quote character are never accepted: the SOP and the
# task instructions spell these values out verbatim, without quotes.
QUOTE_CHARS = '"\'`‘’‚‛“”„‟«»‹›'
DASH_CHARS = '‐‑‒–—―−'
MONTHS = {
    'jan': 1, 'january': 1, 'feb': 2, 'february': 2, 'mar': 3, 'march': 3,
    'apr': 4, 'april': 4, 'may': 5, 'jun': 6, 'june': 6, 'jul': 7, 'july': 7,
    'aug': 8, 'august': 8, 'sep': 9, 'sept': 9, 'september': 9, 'oct': 10,
    'october': 10, 'nov': 11, 'november': 11, 'dec': 12, 'december': 12,
}


def text_of(val):
    return '' if val is None else str(val).strip()


def norm(val):
    return text_of(val).lower()


def is_quoted(val):
    s = text_of(val)
    return bool(s) and (s[0] in QUOTE_CHARS or s[-1] in QUOTE_CHARS)


def quoted_msg(prefix, field, val):
    return f'{prefix}{field} {text_of(val)!r} is quoted; quoted values are not accepted'


def parse_amount(val):
    if val is None or isinstance(val, bool):
        return None
    if isinstance(val, (int, float)):
        return float(val)
    s = text_of(val)
    if is_quoted(s):
        return None
    s = s.replace('$', '').replace(',', '').replace(' ', '')
    try:
        return float(s)
    except ValueError:
        return None


def shown(value, formula):
    """Cell as reported in feedback; flags formulas whose result was never saved."""
    if value is None and isinstance(formula, str) and formula.startswith('='):
        return f'formula {formula} with no cached value (save the workbook with computed values)'
    return 'None' if value is None else str(value)


def _date(y, m, d):
    y = int(y)
    if y < 100:
        y += 2000
    try:
        return datetime.date(y, int(m), int(d))
    except ValueError:
        return None


def extract_dates(val):
    """All calendar dates in a cell, in order of appearance.

    Accepts date/datetime cells, M/D/YYYY, MM/DD/YYYY, M/D/YY, M-D-YYYY, YYYY-MM-DD
    (optionally followed by a time), 'May 5, 2026', '5 May 2026', an optional weekday
    prefix, and compact ranges such as 'May 5-8, 2026' or 'May 5 - May 8, 2026'.
    Any dash-like glyph counts as a dash.
    """
    if isinstance(val, datetime.datetime):
        return [val.date()]
    if isinstance(val, datetime.date):
        return [val]
    s = text_of(val).translate({ord(c): '-' for c in DASH_CHARS})
    found = []

    def take(match, *dates):
        nonlocal s
        if any(d is None for d in dates):
            return
        found.extend((match.start() + i, d) for i, d in enumerate(dates))
        s = s[:match.start()] + ' ' * (match.end() - match.start()) + s[match.end():]

    MON = r'([A-Za-z]{3,9})\.?'
    ORD = r'(?:st|nd|rd|th)?'
    SEP = r'\s*(?:-|to|through|thru)\s*'
    for m in list(re.finditer(r'\b' + MON + r'\s+(\d{1,2})' + ORD + SEP + MON + r'\s+(\d{1,2})' + ORD + r',?\s+(\d{4})\b', s)):
        m1, m2 = MONTHS.get(m.group(1).lower()), MONTHS.get(m.group(3).lower())
        if m1 and m2:
            take(m, _date(m.group(5), m1, m.group(2)), _date(m.group(5), m2, m.group(4)))
    for m in list(re.finditer(r'\b' + MON + r'\s+(\d{1,2})' + ORD + SEP + r'(\d{1,2})' + ORD + r',?\s+(\d{4})\b', s)):
        mo = MONTHS.get(m.group(1).lower())
        if mo:
            take(m, _date(m.group(4), mo, m.group(2)), _date(m.group(4), mo, m.group(3)))
    for m in list(re.finditer(r'\b' + MON + r'\s+(\d{1,2})' + ORD + r',?\s+(\d{4})\b', s)):
        mo = MONTHS.get(m.group(1).lower())
        if mo:
            take(m, _date(m.group(3), mo, m.group(2)))
    for m in list(re.finditer(r'\b(\d{1,2})' + ORD + r'\s+' + MON + r',?\s+(\d{4})\b', s)):
        mo = MONTHS.get(m.group(2).lower())
        if mo:
            take(m, _date(m.group(3), mo, m.group(1)))
    for m in list(re.finditer(r'(?<!\d)(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?!\d)', s)):
        take(m, _date(m.group(1), m.group(2), m.group(3)))
    for m in list(re.finditer(r'(?<!\d)(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})(?!\d)', s)):
        take(m, _date(m.group(3), m.group(1), m.group(2)))
    found.sort(key=lambda item: item[0])
    return [d for _, d in found]


def date_matches(actual, expected):
    """expected is 'M/D/YYYY' or 'M/D/YYYY - M/D/YYYY'. A single date must be the only date in
    the cell. A range is matched by both endpoints in order or, as before, by a single date
    equal to either endpoint."""
    if is_quoted(actual):
        return False
    exp = extract_dates(expected)
    act = extract_dates(actual)
    if not act:
        return False
    if len(exp) == 1:
        return act == exp
    return act == exp or (len(act) == 1 and act[0] in exp)


def find_sheet(wb, first, last):
    """Worksheet whose name holds both name parts (any order, any case); falls back to the
    surname alone. Quoted sheet names are not accepted."""
    names = [n for n in wb.sheetnames if not is_quoted(n)]
    for n in names:
        if first in n.lower() and last in n.lower():
            return wb[n]
    for n in names:
        if last in n.lower():
            return wb[n]
    return None


def open_sheets(workspace_path, first, last, display):
    """(values_ws, formulas_ws, None) or (None, None, error_result). Values come from the
    cached results (data_only); the second load exposes formulas so a formula cell without a
    cached value can be reported as such."""
    xlsx_path = Path(workspace_path) / 'expense_reports.xlsx'
    if not xlsx_path.exists():
        return None, None, {'pass': False, 'score': 0.0, 'feedback': 'expense_reports.xlsx not found'}
    try:
        wb_values = openpyxl.load_workbook(xlsx_path, data_only=True)
        wb_formulas = openpyxl.load_workbook(xlsx_path)
    except Exception as e:
        return None, None, {'pass': False, 'score': 0.0, 'feedback': f'Failed to open: {e}'}
    ws = find_sheet(wb_values, first, last)
    if ws is None:
        return None, None, {'pass': False, 'score': 0.0,
                            'feedback': f'Sheet "{display}" not found (sheets: {wb_values.sheetnames})'}
    return ws, wb_formulas[ws.title], None


def cell_pair(ws_values, ws_formulas, row, col):
    return ws_values.cell(row=row, column=col).value, ws_formulas.cell(row=row, column=col).value


def line_rows(ws_values, ws_formulas):
    """Line-item rows keyed by the Jira key in column A (exactly OPS-<n>, unquoted). Also
    returns the raw text of any quoted column-A key so the failure can say so."""
    rows, quoted = {}, {}
    for row in ws_values.iter_rows(min_row=1, max_col=1):
        key = text_of(row[0].value)
        if not key:
            continue
        if re.fullmatch(r'OPS-\d+', key):
            rows[key] = [cell_pair(ws_values, ws_formulas, row[0].row, c) for c in range(1, 9)]
        elif is_quoted(key):
            bare = key.strip(QUOTE_CHARS).strip()
            if re.fullmatch(r'OPS-\d+', bare):
                quoted[bare] = key
    return rows, quoted


def check_line(jira_key, cells, exp_date, exp_merchant, exp_amount, exp_category,
               exp_approved, exp_denied, tol_amount, tol_approved, tol_denied):
    issues = []
    p = f'{jira_key}: '
    _, (date_v, date_f), (merch_v, merch_f), (amt_v, amt_f), (cat_v, cat_f), \
        (appr_v, appr_f), (den_v, den_f), _ = cells
    if is_quoted(date_v):
        issues.append(quoted_msg(p, 'date', date_v))
    elif not date_matches(date_v, exp_date):
        issues.append(f'{p}date expected "{exp_date}", got "{shown(date_v, date_f)}"')
    if is_quoted(merch_v):
        issues.append(quoted_msg(p, 'merchant', merch_v))
    else:
        am, em = norm(merch_v), exp_merchant.lower()
        if not am or (em not in am and am not in em):
            issues.append(f'{p}merchant expected "{exp_merchant}", got "{shown(merch_v, merch_f)}"')
    amt = parse_amount(amt_v)
    if amt is None or abs(amt - exp_amount) > tol_amount:
        issues.append(f'{p}amount expected {exp_amount}, got "{shown(amt_v, amt_f)}"')
    if is_quoted(cat_v):
        issues.append(quoted_msg(p, 'category', cat_v))
    else:
        ac, ec = norm(cat_v), exp_category.lower()
        if not ac or (ec not in ac and ac not in ec):
            issues.append(f'{p}category expected "{exp_category}", got "{shown(cat_v, cat_f)}"')
    appr = parse_amount(appr_v)
    if appr is None or abs(appr - exp_approved) > tol_approved:
        issues.append(f'{p}approved expected {exp_approved}, got "{shown(appr_v, appr_f)}"')
    if is_quoted(den_v):
        issues.append(quoted_msg(p, 'denied amount', den_v))
    else:
        den = parse_amount(den_v)
        if den is None:
            den = 0.0  # blank, '-', etc. mean nothing denied
        if abs(den - exp_denied) > tol_denied:
            issues.append(f'{p}denied expected {exp_denied}, got "{shown(den_v, den_f)}"')
    return issues


def summary_entries(ws_values, ws_formulas):
    """(label, value, formula) triples below the 'Report Summary' marker in column A, or None."""
    start = None
    for row in ws_values.iter_rows(min_row=1, max_col=1):
        a = row[0].value
        if a is None or is_quoted(a):
            continue
        if 'report summary' in norm(a) or re.sub(r'\s+', '', norm(a)) == 'reportsummary':
            start = row[0].row
            break
    if start is None:
        return None
    entries = []
    for r in range(start + 1, start + 21):
        label = text_of(ws_values.cell(row=r, column=1).value)
        if label:
            entries.append((label,) + cell_pair(ws_values, ws_formulas, r, 2))
    return entries


def find_label(entries, *candidates):
    """First unquoted label containing one of the candidates (tried in order), as
    (label, value, formula); None if absent."""
    for cand in candidates:
        for label, value, formula in entries:
            if not is_quoted(label) and cand in norm(label):
                return label, value, formula
    return None


def quoted_label(entries, *candidates):
    for cand in candidates:
        for label, _, _ in entries:
            if is_quoted(label) and cand in norm(label):
                return label
    return None


def check_summary(entries, jira_key, total_approved, tol_approved, total_denied, tol_denied,
                  status_ok, status_display, comment):
    failures = []

    def lookup(field, *cands):
        hit = find_label(entries, *cands)
        if hit is None:
            q = quoted_label(entries, *cands)
            failures.append(f'{field}: label {q!r} is quoted; quoted text is not accepted' if q
                            else f'{field}: no label found in Report Summary')
        return hit

    hit = lookup('Jira Key', 'jira key', 'jirakey', 'jira')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Jira Key', v))
        elif norm(v) != jira_key.lower():
            failures.append(f'Jira Key expected {jira_key}, got "{shown(v, f)}"')
    hit = lookup('Total Approved', 'total approved', 'totalapproved', 'approved total')
    if hit:
        _, v, f = hit
        ta = parse_amount(v)
        if ta is None or abs(ta - total_approved) > tol_approved:
            failures.append(f'Total Approved expected {total_approved} (±{tol_approved}), got "{shown(v, f)}"')
    hit = lookup('Total Denied', 'total denied', 'totaldenied', 'denied total')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Total Denied', v))
        else:
            td = parse_amount(v)
            if td is None:
                td = 0.0  # blank means nothing denied
            if abs(td - total_denied) > tol_denied:
                failures.append(f'Total Denied expected {total_denied}, got "{shown(v, f)}"')
    hit = lookup('Final Status', 'final status', 'finalstatus', 'status')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Final Status', v))
        elif not status_ok(norm(v)):
            failures.append(f'Final Status expected "{status_display}", got "{shown(v, f)}"')
    hit = lookup('Manager Notified', 'manager notified', 'managernotified', 'notified')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Manager Notified', v))
        elif norm(v) not in ('n', 'no'):
            failures.append(f'Manager Notified expected "N", got "{shown(v, f)}"')
    hit = lookup('Comments', 'comment')
    if hit:
        _, v, f = hit
        if is_quoted(v):
            failures.append(quoted_msg('', 'Comment', v))
        else:
            cv, ce = norm(v), comment.lower()
            if cv != ce and ce not in cv:
                failures.append(f'Comment expected "{comment}", got "{shown(v, f)}"')
    return failures


def verify(workspace_path, external_services_path=None):
    ws, wsf, err = open_sheets(workspace_path, 'leila', 'rahimi', 'Leila Rahimi')
    if err:
        return err
    entries = summary_entries(ws, wsf)
    if entries is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No "Report Summary" section found in Leila Rahimi sheet'}
    failures = check_summary(
        entries, jira_key='OPS-57', total_approved=2966.61, tol_approved=1.50,
        total_denied=115.73, tol_denied=1.50,
        status_ok=lambda fs: 'partial' in fs,
        status_display='Partially Approved', comment='T&E review complete. Expenses approved except where noted.')
    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': 'Leila Rahimi summary issues: ' + '; '.join(failures)}
    return {'pass': True, 'score': 1.0,
            'feedback': 'Leila Rahimi Report Summary verified: Jira Key OPS-57, Total Approved 2966.61, '
                        'Total Denied 115.73, Final Status Partially Approved, Manager Notified N, correct comment'}

from pathlib import Path
import json
import re
from datetime import datetime

def verify(workspace_path, external_services_path=None):
