        key_str = str(cell_a).strip()
        if re.match(r'OPS-\d+$', key_str):
            row_vals = [c.value for c in row]
            rows_by_key[key_str] = row_vals

    def parse_amount(val):
        """Parse a dollar amount from various formats, return float or None."""
        if val is None:
            return None
        if isinstance(val, (int, float)):
            return float(val)
        s = str(val).strip()
        # Remove $, commas
        s = s.replace('$', '').replace(',', '').strip()
        try:
            return float(s)
        except ValueError:
            return None

    def parse_date(val):
        """Normalize date to a comparable string. Return lowercased string."""
        if val is None:
            return ''
        if isinstance(val, datetime):
            return val.strftime('%-m/%-d/%Y').replace('/0', '/').lstrip('0') if False else val.strftime('%m/%d/%Y').lstrip('0').replace('/0', '/')
        s = str(val).strip()
        return s

    def dates_match(actual, expected):
        """Compare a date or both exact endpoints of a date range."""
        if actual is None:
            return False

        def parse_endpoint(value):
            if isinstance(value, datetime):
                return value.strftime('%Y-%m-%d')
            value = str(value).strip()
            for fmt in ['%m/%d/%Y', '%Y-%m-%d', '%m/%d/%y', '%d/%m/%Y']:
                try:
                    return datetime.strptime(value, fmt).strftime('%Y-%m-%d')
                except ValueError:
                    continue
            return None

        def parse_range(value):
            # Normalize Unicode hyphen/dash/minus glyphs before locating the separator.
            normalized = str(value).translate(
                str.maketrans({ord(ch): '-' for ch in '‐‑‒–—―−'})
            )
            date_token = r'(?:\d{1,2}/\d{1,2}/\d{2,4}|\d{4}-\d{1,2}-\d{1,2})'
            match = re.fullmatch(
                r'\s*(' + date_token + r')\s*-\s*(' + date_token + r')\s*',
                normalized,
            )
            if match is None:
                return None
            start = parse_endpoint(match.group(1))
            end = parse_endpoint(match.group(2))
            return (start, end) if start is not None and end is not None else None

        expected_range = parse_range(expected)
        if expected_range is not None:
            return parse_range(actual) == expected_range
        expected_date = parse_endpoint(expected)
        return expected_date is not None and parse_endpoint(actual) == expected_date

    def merchant_matches(actual, expected):
        if actual is None:
            return False
        a = str(actual).strip().lower()
        e = expected.strip().lower()
        # Fuzzy: check containment or near match
        if a == e:
            return True
        if e in a or a in e:
            return True
        # Remove punctuation
        def depunct(s):
            return re.sub(r'[^a-z0-9 ]', '', s)
        return depunct(a) == depunct(e)

    def category_matches(actual, expected):
        if actual is None:
            return False
        a = str(actual).strip().lower()
        e = expected.strip().lower()
        return a == e or e in a or a in e

    def amount_close(actual, expected, tol=0.05):
        a = parse_amount(actual)
        if a is None:
            return False
        return abs(a - expected) <= tol

    def denied_is_zero(val):
        if val is None or str(val).strip() == '':
            return True
        a = parse_amount(val)
        if a is None:
            return True  # empty/non-numeric is fine
        return abs(a) < 0.01

    def denial_reason_empty(val):
        if val is None:
            return True
        s = str(val).strip()
        return s == '' or s.lower() == 'none' or s == '0'

    def is_mileage_amount(val, expected_miles):
        """Check if the amount cell is either the mileage string or the dollar equivalent."""
        if val is None:
            return False
        s = str(val).strip().lower()
        # Check for mileage string
        if str(expected_miles) in s and 'mile' in s:
            return True
        # Check for dollar equivalent
        dollar = expected_miles * 0.725
        a = parse_amount(val)
        if a is not None and abs(a - dollar) < 0.10:
            return True
        if a is not None and abs(a - expected_miles) < 0.10:
            return True
        return False

    # Define expected rows
    # Format: (jira_key, date, merchant, amount_or_miles, is_mileage, miles_count, category, approved_amount, approved_tol, denied_zero)
    expected_rows = [
        ('OPS-59', '5/5/2026', 'Self drove (mileage)', None, True, 357, 'Staff Expense', 258.83, 0.05),
        ('OPS-58', '5/5/2026', 'Sable & Oak Kitchen', 38.59, False, 0, 'Staff Expense', 38.59, 0.05),
        ('OPS-60', '5/6/2026', 'Gloriana Bakery', 9.10, False, 0, 'Staff Expense', 9.10, 0.05),
        ('OPS-61', '5/6/2026', 'Wicker Park Kitchen', 21.22, False, 0, 'Staff Expense', 21.22, 0.05),
        ('OPS-62', '5/6/2026', 'Harbor Light Bistro', 45.20, False, 0, 'Staff Expense', 45.20, 0.05),
        ('OPS-63', '5/7/2026', 'Gloriana Bakery', 10.47, False, 0, 'Staff Expense', 10.47, 0.05),
        ('OPS-64', '5/7/2026', 'Bucktown Bites', 26.40, False, 0, 'Staff Expense', 26.40, 0.05),
        ('OPS-65', '5/7/2026', 'Mariscos Del Lago', 33.07, False, 0, 'Staff Expense', 33.07, 0.05),
        ('OPS-66', '5/8/2026', 'Gloriana Bakery', 11.02, False, 0, 'Staff Expense', 11.02, 0.05),
        ('OPS-67', '5/8/2026', 'Lincoln Square Cafe', 26.13, False, 0, 'Staff Expense', 26.13, 0.05),
        ('OPS-68', '5/9/2026', 'Gloriana Bakery', 11.85, False, 0, 'Staff Expense', 11.85, 0.05),
        ('OPS-69', '5/9/2026', 'Loop Street Deli', 25.63, False, 0, 'Staff Expense', 25.63, 0.05),
        ('OPS-70', '5/9/2026', 'Koto Ramen & Izakaya', 39.69, False, 0, 'Staff Expense', 39.69, 0.05),
        ('OPS-71', '5/5/2026 - 5/9/2026', 'Hyatt Regency Chicago', 1916.99, False, 0, 'Staff Expense', 1916.99, 0.05),
        ('OPS-72', '5/10/2026', 'Gloriana Bakery', 11.30, False, 0, 'Staff Expense', 11.30, 0.05),
        ('OPS-73', '5/10/2026', 'Self drove (mileage)', None, True, 360, 'Staff Expense', 261.00, 0.05),
    ]

    for exp in expected_rows:
        jira_key, exp_date, exp_merchant, exp_amount, is_mileage, miles, exp_category, exp_approved, tol = exp
        total_checks += 1

        if jira_key not in rows_by_key:
            feedback_parts.append(f'FAIL: Row {jira_key} not found in worksheet')
            continue

        row = rows_by_key[jira_key]
        # Columns: A=JiraKey(0), B=Date(1), C=Merchant(2), D=Amount(3), E=Category(4), F=Approved(5), G=Denied(6), H=DenialReason(7)
        row_ok = True
        row_issues = []

        # Check Date (col B, index 1)
        if not dates_match(row[1], exp_date):
            row_ok = False
            row_issues.append(f'Date: expected "{exp_date}", got "{row[1]}"')

        # Check Merchant (col C, index 2)
        if not merchant_matches(row[2], exp_merchant):
            row_ok = False
            row_issues.append(f'Merchant: expected "{exp_merchant}", got "{row[2]}"')

        # Check Amount (col D, index 3)
        if is_mileage:
            if not is_mileage_amount(row[3], miles):
                row_ok = False
                row_issues.append(f'Amount: expected "{miles} miles" or ${miles*0.725:.2f}, got "{row[3]}"')
        else:
            if not amount_close(row[3], exp_amount, 0.05):
                row_ok = False
                row_issues.append(f'Amount: expected {exp_amount}, got "{row[3]}"')

        # Check Category (col E, index 4)
        if not category_matches(row[4], exp_category):
            row_ok = False
            row_issues.append(f'Category: expected "{exp_category}", got "{row[4]}"')

        # Check Approved Amount (col F, index 5)
        if not amount_close(row[5], exp_approved, tol):
            row_ok = False
            row_issues.append(f'Approved Amount: expected {exp_approved} (±{tol}), got "{row[5]}"')

        # Check Denied Amount (col G, index 6)
        denied_val = row[6] if len(row) > 6 else None
        if not denied_is_zero(denied_val):
            row_ok = False
            row_issues.append(f'Denied Amount: expected 0 or empty, got "{denied_val}"')

        # Check Denial Reason (col H, index 7) must be empty
        reason_val = row[7] if len(row) > 7 else None
        if not denial_reason_empty(reason_val):
            row_ok = False
            row_issues.append(f'Denial Reason: expected empty, got "{reason_val}"')

        if row_ok:
            passed_checks += 1
            feedback_parts.append(f'PASS: Row {jira_key} matches expected values')
        else:
            feedback_parts.append(f'FAIL: Row {jira_key}: {"; ".join(row_issues)}')

    score = passed_checks / total_checks if total_checks > 0 else 0.0
    passed = passed_checks == total_checks  # rubric requires every listed row correct

    feedback = f'Hiroshi Tanaka worksheet: {passed_checks}/{total_checks} rows correct (score={score:.2f}).\n' + '\n'.join(feedback_parts)
    return {'pass': passed, 'score': score, 'feedback': feedback}

from pathlib import Path
import re

def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
    except ImportError:
        return {"pass": False, "score": 0.0, "feedback": "openpyxl not available"}

    file_path = Path(workspace_path) / "expense_reports.xlsx"
    if not file_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"File not found: {file_path}"}

    wb = openpyxl.load_workbook(str(file_path), data_only=True)

    # Find Hiroshi Tanaka worksheet (case-insensitive match)
    target_ws = None
    for name in wb.sheetnames:
        if name.strip().lower() == "hiroshi tanaka":
            target_ws = wb[name]
            break

    if target_ws is None:
        return {"pass": False, "score": 0.0, "feedback": f"Worksheet 'Hiroshi Tanaka' not found. Available sheets: {wb.sheetnames}"}

    # Collect all rows as (col_a, col_b) pairs
    # We need to find the Report Summary section and then look for label-value pairs
    rows = []
    for row in target_ws.iter_rows(min_row=1, max_col=2, values_only=True):
        rows.append(row)

    # Find the Report Summary header row
    summary_start = None
    for i, (a, b) in enumerate(rows):
        if a is not None and str(a).strip().lower().replace(" ", "") == "reportsummary":
            summary_start = i
            break

    if summary_start is None:
        return {"pass": False, "score": 0.0, "feedback": "Could not find 'Report Summary' header in column A of Hiroshi Tanaka worksheet."}

    # Extract label->value mapping from summary section
    summary = {}
    for i in range(summary_start + 1, len(rows)):
        a, b = rows[i]
        if a is not None:
            key = str(a).strip()
            summary[key.lower()] = (key, b)

    feedback_parts = []
    checks_passed = 0
    total_checks = 6

    def clean_num(val):
        """Try to extract a numeric value from val."""
        if val is None:
            return None
        if isinstance(val, (int, float)):
            return float(val)
        s = str(val).strip()
        # Remove currency symbols, commas, spaces
        s = re.sub(r'[\$€£¥,\s]', '', s)
        try:
            return float(s)
        except ValueError:
            return None

    def find_label(possible_keys):
        """Find a summary entry matching any of the possible key strings (case-insensitive)."""
        for pk in possible_keys:
            pk_lower = pk.lower()
            for sk in summary:
                if pk_lower in sk or sk in pk_lower:
                    return summary[sk]
        return None

    # 1. Jira Key
    entry = find_label(["jira key", "jirakey", "jira"])
    if entry:
        orig_label, val = entry
        val_str = str(val).strip() if val is not None else ""
        if val_str.upper() == "OPS-HR-TE-TANAKA-2026-05-11" or val_str == "OPS-74":
            checks_passed += 1
            feedback_parts.append(f"PASS: Jira Key = '{val_str}'")
        else:
            feedback_parts.append(f"FAIL: Jira Key expected 'OPS-74', got '{val_str}'")
    else:
        feedback_parts.append("FAIL: No 'Jira Key' label found in Report Summary.")

    # 2. Total Approved ~ 2746.49 ± 1.00
    entry = find_label(["total approved", "totalapproved"])
    if entry:
        orig_label, val = entry
        num = clean_num(val)
        if num is not None and abs(num - 2746.49) <= 1.00:
            checks_passed += 1
            feedback_parts.append(f"PASS: Total Approved = {num}")
        else:
            feedback_parts.append(f"FAIL: Total Approved expected ~2746.49 (±1.00), got '{val}' (parsed as {num})")
    else:
        feedback_parts.append("FAIL: No 'Total Approved' label found in Report Summary.")

    # 3. Total Denied = 0
    entry = find_label(["total denied", "totaldenied"])
    if entry:
        orig_label, val = entry
        num = clean_num(val)
        if num is not None and abs(num - 0) <= 0.01:
            checks_passed += 1
            feedback_parts.append(f"PASS: Total Denied = {num}")
        else:
            # Also accept string "0" or blank/None as 0
            val_str = str(val).strip() if val is not None else ""
            if val_str in ["", "0", "0.0", "0.00", "$0", "$0.00"]:
                checks_passed += 1
                feedback_parts.append(f"PASS: Total Denied = '{val_str}' (treated as 0)")
            else:
                feedback_parts.append(f"FAIL: Total Denied expected 0, got '{val}' (parsed as {num})")
    else:
        feedback_parts.append("FAIL: No 'Total Denied' label found in Report Summary.")

    # 4. Final Status = Approved
    entry = find_label(["final status", "finalstatus", "status"])
    if entry:
        orig_label, val = entry
        val_str = str(val).strip() if val is not None else ""
        if val_str.lower() == "approved":
            checks_passed += 1
            feedback_parts.append(f"PASS: Final Status = '{val_str}'")
        else:
            feedback_parts.append(f"FAIL: Final Status expected 'Approved', got '{val_str}'")
    else:
        feedback_parts.append("FAIL: No 'Final Status' label found in Report Summary.")

    # 5. Manager Notified = N
    entry = find_label(["manager notified", "managernotified"])
    if entry:
        orig_label, val = entry
        val_str = str(val).strip() if val is not None else ""
        if val_str.upper() in ["N", "NO"]:
            checks_passed += 1
            feedback_parts.append(f"PASS: Manager Notified = '{val_str}'")
        else:
            feedback_parts.append(f"FAIL: Manager Notified expected 'N', got '{val_str}'")
    else:
        feedback_parts.append("FAIL: No 'Manager Notified' label found in Report Summary.")

    # 6. Comment(s) = "T&E review complete. All expenses approved."
    entry = find_label(["comment", "comments"])
    if entry:
        orig_label, val = entry
        val_str = str(val).strip() if val is not None else ""
        expected = "T&E review complete. All expenses approved."
        # Flexible comparison: case-insensitive, ignore trailing/leading whitespace
        if val_str.lower() == expected.lower() or expected.lower() in val_str.lower():
            checks_passed += 1
            feedback_parts.append(f"PASS: Comments = '{val_str}'")
        else:
            feedback_parts.append(f"FAIL: Comments expected '{expected}', got '{val_str}'")
    else:
        feedback_parts.append("FAIL: No 'Comment'/'Comments' label found in Report Summary.")

    score = checks_passed / total_checks
    passed = checks_passed == total_checks
    feedback = f"Hiroshi Tanaka Report Summary: {checks_passed}/{total_checks} checks passed.\n" + "\n".join(feedback_parts)

    return {"pass": passed, "score": score, "feedback": feedback}

from pathlib import Path
import re
import datetime

def verify(workspace_path, external_services_path=None):
    import openpyxl

    filepath = Path(workspace_path) / "expense_reports.xlsx"
    if not filepath.exists():
        return {"pass": False, "score": 0.0, "feedback": "File expense_reports.xlsx not found."}

    wb = openpyxl.load_workbook(str(filepath))

    sheet = None
    for name in wb.sheetnames:
        if "carlos" in name.lower() and "mendez" in name.lower():
            sheet = wb[name]
            break
    if sheet is None:
        return {"pass": False, "score": 0.0, "feedback": f"Worksheet 'Carlos Mendez' not found. Available sheets: {wb.sheetnames}"}

    rows_by_key = {}
    for row in sheet.iter_rows(min_row=1, values_only=False):
        cell_a = row[0].value
        key = str(cell_a).strip() if cell_a is not None else ""
        if re.match(r'OPS-\d+$', key):
            vals = [c.value for c in row]
            rows_by_key[key] = vals

    def parse_num(v):
        if v is None:
            return 0.0
        if isinstance(v, (int, float)):
            return float(v)
        s = str(v).strip().replace("$", "").replace(",", "").strip()
        if s == "" or s.lower() == "none":
            return 0.0
        try:
            return float(s)
        except ValueError:
            return None

    def nums_close(a, b, tol=0.05):
        if a is None or b is None:
            return False
        if abs(b) < 0.01:
            return abs(a) < 0.01 + tol
        return abs(a - b) <= max(abs(b) * tol, 0.05)

    def normalize_str(s):
        if s is None:
            return ""
        return str(s).strip().lower()

    def parse_date_tuple(val):
        if val is None:
            return None
        if isinstance(val, (datetime.datetime, datetime.date)):
            return (val.month, val.day, val.year)
        s = str(val).strip()
        m = re.match(r'(\d{1,2})/(\d{1,2})/(\d{4})', s)
        if m:
            return (int(m.group(1)), int(m.group(2)), int(m.group(3)))
        m = re.match(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
        if m:
            return (int(m.group(2)), int(m.group(3)), int(m.group(1)))
        return None

    def date_matches(actual_cell, expected_str):
        exp_lower = expected_str.lower().strip()
        # Range expected
        if ' - ' in exp_lower:
            parts = re.findall(r'(\d{1,2})/(\d{1,2})/(\d{4})', exp_lower)
            if len(parts) >= 2:
                start = (int(parts[0][0]), int(parts[0][1]), int(parts[0][2]))
                end = (int(parts[1][0]), int(parts[1][1]), int(parts[1][2]))
                act_str = normalize_str(actual_cell)
                if all(f"{m}/{d}" in act_str or f"{m:02d}/{d:02d}" in act_str
                       for m, d, _ in (start, end)):
                    return True
                act_tuple = parse_date_tuple(actual_cell)
                if act_tuple in (start, end):
                    return True
                return False
        # Single date expected
        exp_tuple = parse_date_tuple(expected_str)
        act_tuple = parse_date_tuple(actual_cell)
        if exp_tuple and act_tuple and exp_tuple == act_tuple:
            return True
        act_str = normalize_str(actual_cell)
        if exp_lower in act_str or act_str in exp_lower:
            return True
        return False

    def merchant_matches(cell_val, expected):
        if cell_val is None:
            return False
        return normalize_str(cell_val) == normalize_str(expected) or normalize_str(expected) in normalize_str(cell_val)

    def category_matches(cell_val, expected):
        return normalize_str(cell_val) == normalize_str(expected)

    def denial_reason_blank(cell_val):
        v = normalize_str(cell_val)
        return v == "" or v == "none" or v == "n/a" or v == "0"

    def denial_reason_present(cell_val, keywords):
        v = normalize_str(cell_val)
        if v == "" or v == "none":
            return False
        for kw in keywords:
            if kw.lower() not in v:
                return False
        return True

    expected = [
        {"key": "OPS-19", "date": "5/5/2026", "merchant": "Delta", "amount": 384.40, "category": "Staff Expense", "approved": 384.40, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-20", "date": "5/5/2026", "merchant": "Cosa Nostra Cucina", "amount": 46.86, "category": "Staff Expense", "approved": 46.86, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-21", "date": "5/6/2026", "merchant": "Bucktown Bites", "amount": 28.11, "category": "Staff Expense", "approved": 28.11, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-22", "date": "5/6/2026", "merchant": "Sable & Oak Kitchen", "amount": 48.23, "category": "Staff Expense", "approved": 48.23, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-23", "date": "5/6/2026", "merchant": "Art Institute of Chicago", "amount": 32.00, "category": "Staff Expense", "approved": 0, "denied": 32.00, "denial_reason_required": True, "denial_keywords": ["business justification", "personal"]},
        {"key": "OPS-24", "date": "5/7/2026", "merchant": "Lincoln Square Cafe", "amount": 24.25, "category": "Staff Expense", "approved": 24.25, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-25", "date": "5/7/2026", "merchant": "Blackstone Chophouse", "amount": 46.86, "category": "Staff Expense", "approved": 46.86, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-26", "date": "5/8/2026", "merchant": "Loop Street Deli", "amount": 21.22, "category": "Staff Expense", "approved": 21.22, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-27", "date": "5/8/2026", "merchant": "Cosa Nostra Cucina", "amount": 43.55, "category": "Staff Expense", "approved": 43.55, "denied": 0, "denial_reason_required": False},
        {"key": "OPS-28", "date": "5/9/2026", "merchant": "Gloriana Bakery", "amount": 13.73, "category": "Staff Expense", "daily_cap_meal": True},
        {"key": "OPS-29", "date": "5/9/2026", "merchant": "The Riverwalk Grille", "amount": 36.93, "category": "Staff Expense", "daily_cap_meal": True},
        {"key": "OPS-30", "date": "5/9/2026", "merchant": "Harbor Light Bistro", "amount": 43.55, "category": "Staff Expense", "daily_cap_meal": True},
        {"key": "OPS-31", "date": "5/5/2026 - 5/9/2026", "merchant": "Hyatt Regency Chicago", "amount": 1916.99, "category": "Staff Expense", "approved": 1916.99, "denied": 0, "denial_reason_required": False},
    ]

    errors = []
    passed = 0
    total = len(expected) + 1
    daily_cap_denied = 0.0

    for exp in expected:
        key = exp["key"]
        found_row = None
        for rk, rv in rows_by_key.items():
            if normalize_str(rk) == normalize_str(key):
                found_row = rv
                break
        if found_row is None:
            for rk, rv in rows_by_key.items():
                if normalize_str(key) in normalize_str(rk) or normalize_str(rk) in normalize_str(key):
                    found_row = rv
                    break
        if found_row is None:
            errors.append(f"Row {key}: Not found in worksheet.")
            continue

        row_errors = []
        if not date_matches(found_row[1], exp["date"]):
            row_errors.append(f"Date: expected '{exp['date']}', got '{found_row[1]}'")
        if not merchant_matches(found_row[2], exp["merchant"]):
            row_errors.append(f"Merchant: expected '{exp['merchant']}', got '{found_row[2]}'")
        actual_amount = parse_num(found_row[3])
        if not nums_close(actual_amount, exp["amount"]):
            row_errors.append(f"Amount: expected {exp['amount']}, got {found_row[3]}")
        if not category_matches(found_row[4], exp["category"]):
            row_errors.append(f"Category: expected '{exp['category']}', got '{found_row[4]}'")
        actual_approved = parse_num(found_row[5])
        actual_denied = parse_num(found_row[6])
        if exp.get("daily_cap_meal"):
            if actual_approved is None or actual_denied is None:
                row_errors.append(
                    f"Approved/Denied: expected numeric disposition totaling {exp['amount']}, "
                    f"got {found_row[5]}/{found_row[6]}"
                )
            elif actual_approved < -0.05 or actual_denied < -0.05:
                row_errors.append(
                    f"Approved/Denied: amounts cannot be negative, got "
                    f"{found_row[5]}/{found_row[6]}"
                )
            elif abs(actual_approved + actual_denied - exp["amount"]) > 0.05:
                row_errors.append(
                    f"Approved + Denied: expected {exp['amount']}, got "
                    f"{actual_approved + actual_denied}"
                )
            if actual_denied is not None:
                daily_cap_denied += actual_denied
            reason = found_row[7] if len(found_row) > 7 else None
            if actual_denied is not None and actual_denied > 0.05:
                normalized_reason = normalize_str(reason)
                reason_ok = (
                    "meal" in normalized_reason
                    and any(token in normalized_reason for token in ("daily", "per day", "$100", "100"))
                    and any(token in normalized_reason for token in ("limit", "cap", "exceed", "over"))
                )
                if not reason_ok:
                    row_errors.append(
                        "Denial Reason: expected a daily $100 meal-limit reason, "
                        f"got '{reason}'"
                    )
            elif not denial_reason_blank(reason):
                row_errors.append(f"Denial Reason: expected blank, got '{reason}'")
        else:
            if not nums_close(actual_approved, exp["approved"]):
                row_errors.append(f"Approved: expected {exp['approved']}, got {found_row[5]}")
            if not nums_close(actual_denied, exp["denied"]):
                row_errors.append(f"Denied: expected {exp['denied']}, got {found_row[6]}")
        if exp.get("denial_reason_required"):
            if not denial_reason_present(found_row[7] if len(found_row) > 7 else None, exp.get("denial_keywords", [])):
                row_errors.append(f"Denial Reason: expected reason containing {exp.get('denial_keywords', [])}, got '{found_row[7] if len(found_row) > 7 else None}'")
        elif not exp.get("daily_cap_meal"):
            if len(found_row) > 7 and not denial_reason_blank(found_row[7]):
                row_errors.append(f"Denial Reason: expected blank, got '{found_row[7]}'")

        if row_errors:
            errors.append(f"Row {key}: " + "; ".join(row_errors))
        else:
            passed += 1

    if abs(daily_cap_denied - 5.49) > 0.05:
        errors.append(
            "Rows OPS-28/OPS-29/OPS-30: combined daily-cap denial expected "
            f"5.49, got {daily_cap_denied:.2f}"
        )
    else:
        passed += 1

    score = passed / total if total > 0 else 0.0
    if errors:
        feedback = f"Passed {passed}/{total} rows.\nErrors:\n" + "\n".join(errors)
    else:
        feedback = f"All {total} rows verified successfully for Carlos Mendez."

    return {"pass": passed == total, "score": score, "feedback": feedback}

from pathlib import Path
import re
import openpyxl


def verify(workspace_path, external_services_path=None):
    file_path = Path(workspace_path) / "expense_reports.xlsx"
    if not file_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"File not found: {file_path}"}

    wb = openpyxl.load_workbook(str(file_path), data_only=True)

    # Find the Carlos Mendez worksheet (case-insensitive, flexible spacing)
    target_ws = None
    for name in wb.sheetnames:
        if re.search(r'carlos\s+mendez', name, re.IGNORECASE):
            target_ws = wb[name]
            break

    if target_ws is None:
        return {"pass": False, "score": 0.0, "feedback": f"No worksheet matching 'Carlos Mendez' found. Sheets: {wb.sheetnames}"}

    # Read all rows into a list of (colA, colB) tuples
    rows = []
    for row in target_ws.iter_rows(min_row=1, max_col=2, values_only=True):
        a_val = row[0] if row[0] is not None else ""
        b_val = row[1] if len(row) > 1 and row[1] is not None else ""
        rows.append((a_val, b_val))

    # Find the Report Summary section
    summary_start = None
    for i, (a, b) in enumerate(rows):
        if isinstance(a, str) and re.search(r'report\s+summary', a, re.IGNORECASE):
            summary_start = i
            break

    if summary_start is None:
        return {"pass": False, "score": 0.0, "feedback": "'Report Summary' header not found in column A."}

    # Build a dict of label -> value from the summary section
    summary = {}
    for a, b in rows[summary_start + 1:]:
        if isinstance(a, str) and a.strip():
            summary[a.strip().lower()] = b

    # Also check starting from summary_start itself in case labels include that row
    a0, b0 = rows[summary_start]
    if isinstance(a0, str) and a0.strip().lower() != 'report summary':
        summary[a0.strip().lower()] = b0

    def clean_num(val):
        """Extract a numeric value from a cell, stripping currency symbols, commas, etc."""
        if val is None:
            return None
        if isinstance(val, (int, float)):
            return float(val)
        s = str(val).replace('$', '').replace(',', '').replace(' ', '').strip()
        try:
            return float(s)
        except ValueError:
            return None

    def find_key(dictionary, *candidates):
        """Find a value in dict by trying multiple key variations (case-insensitive)."""
        for key in dictionary:
            for c in candidates:
                if re.fullmatch(c, key, re.IGNORECASE):
                    return dictionary[key]
        return None

    checks_passed = 0
    total_checks = 6
    feedback_parts = []

    # 1. Jira Key
    jira_val = find_key(summary, r'jira\s*key')
    if jira_val is not None and re.search(r'OPS-32', str(jira_val), re.IGNORECASE):
        checks_passed += 1
        feedback_parts.append(f"PASS Jira Key: found '{jira_val}'")
    else:
        feedback_parts.append(f"FAIL Jira Key: expected 'OPS-32', found '{jira_val}'")

    # 2. Total Approved ~2649.19 ± 1.00
    approved_val = find_key(summary, r'total\s*approved')
    approved_num = clean_num(approved_val)
    if approved_num is not None and abs(approved_num - 2649.19) <= 1.00:
        checks_passed += 1
        feedback_parts.append(f"PASS Total Approved: {approved_num}")
    else:
        feedback_parts.append(f"FAIL Total Approved: expected ~2649.19 (±1.00), found '{approved_val}' (numeric: {approved_num})")

    # 3. Total Denied == 37.49 (use ±1.00 tolerance)
    denied_val = find_key(summary, r'total\s*denied')
    denied_num = clean_num(denied_val)
    if denied_num is not None and abs(denied_num - 37.49) <= 1.00:
        checks_passed += 1
        feedback_parts.append(f"PASS Total Denied: {denied_num}")
    else:
        feedback_parts.append(f"FAIL Total Denied: expected 37.49 (±1.00), found '{denied_val}' (numeric: {denied_num})")

    # 4. Final Status
    status_val = find_key(summary, r'final\s*status')
    if status_val is not None and re.search(r'partially\s*approved', str(status_val), re.IGNORECASE):
        checks_passed += 1
        feedback_parts.append(f"PASS Final Status: '{status_val}'")
    else:
        feedback_parts.append(f"FAIL Final Status: expected 'Partially Approved', found '{status_val}'")

    # 5. Manager Notified
    notified_val = find_key(summary, r'manager\s*notified')
    if notified_val is not None and str(notified_val).strip().upper() == 'N':
        checks_passed += 1
        feedback_parts.append(f"PASS Manager Notified: '{notified_val}'")
    else:
        feedback_parts.append(f"FAIL Manager Notified: expected 'N', found '{notified_val}'")

    # 6. Comments
    comment_val = find_key(summary, r'comments?')
    expected_comment = "T&E review complete. Expenses approved except where noted."
    if comment_val is not None:
        # Loose comparison: strip, case-insensitive, allow minor punctuation differences
        c_clean = re.sub(r'\s+', ' ', str(comment_val).strip().lower())
        e_clean = re.sub(r'\s+', ' ', expected_comment.strip().lower())
        if c_clean == e_clean or e_clean in c_clean:
            checks_passed += 1
            feedback_parts.append(f"PASS Comment: '{comment_val}'")
        else:
            feedback_parts.append(f"FAIL Comment: expected '{expected_comment}', found '{comment_val}'")
    else:
        feedback_parts.append(f"FAIL Comment: label 'Comment'/'Comments' not found in summary section")

    score = checks_passed / total_checks
    passed = checks_passed == total_checks
    feedback = f"Carlos Mendez Report Summary: {checks_passed}/{total_checks} checks passed.\n" + "\n".join(feedback_parts)
    return {"pass": passed, "score": score, "feedback": feedback}

from pathlib import Path
import openpyxl
import re
import datetime

def verify(workspace_path, external_services_path=None):
    filepath = Path(workspace_path) / "expense_reports.xlsx"
    if not filepath.exists():
        return {"pass": False, "score": 0.0, "feedback": "File expense_reports.xlsx not found."}

    wb = openpyxl.load_workbook(str(filepath))
    sheet = None
    for name in wb.sheetnames:
        if "priya" in name.lower() and "natarajan" in name.lower():
            sheet = wb[name]
            break
    if sheet is None:
        return {"pass": False, "score": 0.0, "feedback": f"Worksheet 'Priya Natarajan' not found. Available sheets: {wb.sheetnames}"}

    rows = []
    for row in sheet.iter_rows(min_row=1, values_only=False):
        vals = [cell.value for cell in row]
        rows.append(vals)

    row_dict = {}
    for r in rows:
        key = str(r[0]).strip() if r[0] is not None else ""
        if key:
            row_dict[key] = r

    def parse_num(val):
        if val is None:
            return None
        if isinstance(val, (int, float)):
            return float(val)
        s = str(val).strip()
        s = re.sub(r'[\$,]', '', s)
        try:
            return float(s)
        except:
            return None

    def normalize_str(val):
        if val is None:
            return ""
        return str(val).strip().lower()

    def parse_date_tuple(val):
        if val is None:
            return None
        if isinstance(val, (datetime.datetime, datetime.date)):
            return (val.month, val.day, val.year)
        s = str(val).strip()
        m = re.match(r'(\d{1,2})/(\d{1,2})/(\d{4})', s)
        if m:
            return (int(m.group(1)), int(m.group(2)), int(m.group(3)))
        m = re.match(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
        if m:
            return (int(m.group(2)), int(m.group(3)), int(m.group(1)))
        return None

    def date_matches(actual_cell, expected_str):
        exp_lower = expected_str.lower().strip()
        if ' - ' in exp_lower or ' to ' in exp_lower:
            parts = re.findall(r'(\d{1,2})/(\d{1,2})/(\d{4})', exp_lower)
            if len(parts) >= 2:
                start = (int(parts[0][0]), int(parts[0][1]), int(parts[0][2]))
                end = (int(parts[1][0]), int(parts[1][1]), int(parts[1][2]))
                act_str = normalize_str(actual_cell)
                # Accept a textual span mentioning both dates (slash or ISO form)
                start_iso = f"{start[2]}-{start[0]:02d}-{start[1]:02d}"
                end_iso = f"{end[2]}-{end[0]:02d}-{end[1]:02d}"
                if (start_iso in act_str and end_iso in act_str):
                    return True
                if all(f"{m}/{d}" in act_str or f"{m:02d}/{d:02d}" in act_str
                       for m, d, _ in (start, end)):
                    return True
                act_tuple = parse_date_tuple(actual_cell)
                if act_tuple in (start, end):
                    return True
                return False
        exp_tuple = parse_date_tuple(expected_str)
        act_tuple = parse_date_tuple(actual_cell)
        if exp_tuple and act_tuple and exp_tuple == act_tuple:
            return True
        act_str = normalize_str(actual_cell)
        if exp_lower in act_str or act_str in exp_lower:
            return True
        return False

    def merchant_matches(cell_val, expected):
        if cell_val is None:
            return False
        return normalize_str(cell_val) == normalize_str(expected) or normalize_str(expected) in normalize_str(cell_val) or normalize_str(cell_val) in normalize_str(expected)

    def category_matches(cell_val, expected):
        if cell_val is None:
            return False
        return normalize_str(expected) in normalize_str(cell_val) or normalize_str(cell_val) in normalize_str(expected)

    def denial_reason_ok(cell_val):
        if cell_val is None:
            return False
        s = normalize_str(cell_val)
        if "business justification" in s or ("justification" in s and ("missing" in s or "no " in s)):
            return True
        if "personal" in s and ("expense" in s or "reimbursement" in s or "claim" in s):
            return True
        # SOP 6.2 step 6c also permits citing the directly violated policy:
        # every Natarajan receipt is from Fort Wayne, IN while the only
        # calendar event is the Chicago conference, so a reason citing the
        # failed business-event/location check (SOP 6.2 step 3) is valid.
        negations = ("no ", "not ", "missing", "without", "lack", "absent",
                     "mismatch", "different", "outside", "unrelated", "invalid")
        subjects = ("calendar", "business event", "business-related event",
                    "company event", "work event", "qualifying event")
        if any(t in s for t in subjects) and any(n in s for n in negations):
            return True
        if "fort wayne" in s and "chicago" in s:
            return True
        if (("same city" in s or "same metropolitan" in s or "same metro" in s
                or "event location" in s or "event city" in s)
                and any(n in s for n in negations)):
            return True
        return False

    expected_rows = [
        {
            "key": "OPS-34",
            "date": "5/5/2026",
            "merchant": "Self drove (mileage)",
            "amount_check": lambda v: ("200" in str(v) and ("mile" in str(v).lower() or "mi" in str(v).lower())) or (parse_num(v) == 200 if v is not None else False),
            "amount_display": "200 miles or equivalent",
            "category": "Staff Expense",
            "approved": 0,
            "denied": 145.00,
            "denied_tol": 0.10
        },
        {
            "key": "OPS-33",
            "date": "5/5/2026",
            "merchant": "Riverfront Deli",
            "amount_check": lambda v: abs((parse_num(v) or -999) - 16.59) < 0.05,
            "amount_display": "16.59",
            "category": "Staff Expense",
            "approved": 0,
            "denied": 16.59,
            "denied_tol": 0.05
        },
        {
            "key": "OPS-35",
            "date": "5/6/2026",
            "merchant": "The Creamery Cafe",
            "amount_check": lambda v: abs((parse_num(v) or -999) - 21.40) < 0.05,
            "amount_display": "21.40",
            "category": "Staff Expense",
            "approved": 0,
            "denied": 21.40,
            "denied_tol": 0.05
        },
        {
            "key": "OPS-36",
            "date": "5/7/2026",
            "merchant": "Canal Street Kitchen",
            "amount_check": lambda v: abs((parse_num(v) or -999) - 16.05) < 0.05,
            "amount_display": "16.05",
            "category": "Staff Expense",
            "approved": 0,
            "denied": 16.05,
            "denied_tol": 0.05
        },
        {
            "key": "OPS-37",
            "date": "5/8/2026",
            "merchant": "The Landing Spot",
            "amount_check": lambda v: abs((parse_num(v) or -999) - 20.33) < 0.05,
            "amount_display": "20.33",
            "category": "Staff Expense",
            "approved": 0,
            "denied": 20.33,
            "denied_tol": 0.05
        },
        {
            "key": "OPS-38",
            "date": "5/5/2026 - 5/9/2026",
            "merchant": "Serenity Hotel and Spa",
            "amount_check": lambda v: abs((parse_num(v) or -999) - 1471.96) < 1.0,
            "amount_display": "1471.96",
            "category": "Staff Expense",
            "approved": 0,
            "denied": 1471.96,
            "denied_tol": 1.0
        }
    ]

    issues = []
    passed_count = 0
    total_checks = len(expected_rows)

    for exp in expected_rows:
        jira_key = exp["key"]
        found_row = None
        for rk, rv in row_dict.items():
            if jira_key.lower() in rk.lower() or rk.lower() in jira_key.lower():
                found_row = rv
                break

        if found_row is None:
            issues.append(f"Row with Jira Key '{jira_key}' not found.")
            continue

        row_issues = []

        date_val = found_row[1] if len(found_row) > 1 else None
        if not date_matches(date_val, exp["date"]):
            row_issues.append(f"Date: expected '{exp['date']}', got '{date_val}'")

        merchant_val = found_row[2] if len(found_row) > 2 else None
        if not merchant_matches(merchant_val, exp["merchant"]):
            merchant_s = normalize_str(merchant_val)
            exp_words = [w.lower() for w in exp["merchant"].split() if len(w) > 2]
            matching_words = sum(1 for w in exp_words if w in merchant_s)
            if matching_words < len(exp_words) * 0.5:
                row_issues.append(f"Merchant: expected '{exp['merchant']}', got '{merchant_val}'")

        amount_val = found_row[3] if len(found_row) > 3 else None
        if not exp["amount_check"](amount_val):
            row_issues.append(f"Amount: expected {exp['amount_display']}, got '{amount_val}'")

        cat_val = found_row[4] if len(found_row) > 4 else None
        if not category_matches(cat_val, exp["category"]):
            row_issues.append(f"Category: expected '{exp['category']}', got '{cat_val}'")

        approved_val = parse_num(found_row[5]) if len(found_row) > 5 else None
        if approved_val is None or abs(approved_val - exp["approved"]) > 0.05:
            row_issues.append(f"Approved Amount: expected {exp['approved']}, got '{found_row[5] if len(found_row) > 5 else None}'")

        denied_val = parse_num(found_row[6]) if len(found_row) > 6 else None
        if denied_val is None or abs(denied_val - exp["denied"]) > exp["denied_tol"]:
            row_issues.append(f"Denied Amount: expected {exp['denied']} (±{exp['denied_tol']}), got '{found_row[6] if len(found_row) > 6 else None}'")

        reason_val = found_row[7] if len(found_row) > 7 else None
        if not denial_reason_ok(reason_val):
            row_issues.append(f"Denial Reason: expected equivalent to 'Missing business justification. Please submit personal reimbursement.', got '{reason_val}'")

        if row_issues:
            issues.append(f"Row '{jira_key}': " + "; ".join(row_issues))
        else:
            passed_count += 1

    score = passed_count / total_checks if total_checks > 0 else 0.0
    passed = passed_count == total_checks

    if passed:
        feedback = f"All {total_checks} line-item rows in 'Priya Natarajan' worksheet verified successfully."
    else:
        feedback = f"{passed_count}/{total_checks} rows passed. Issues:\n" + "\n".join(issues)

    return {"pass": passed, "score": score, "feedback": feedback}

from pathlib import Path
import re
