    # Find the worksheet for Priya Natarajan (case-insensitive match)
    ws = None
    for name in wb.sheetnames:
        if name.strip().lower() == "priya natarajan":
            ws = wb[name]
            break
    if ws is None:
        return {"pass": False, "score": 0.0, "feedback": f"Worksheet 'Priya Natarajan' not found. Found sheets: {wb.sheetnames}"}

    # Build a dict of label -> value from the Report Summary section
    # We scan column A for labels and column B for values
    # The Report Summary section starts after a row containing "Report Summary" in column A
    summary_started = False
    summary = {}  # normalized_label -> raw_value
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=2):
        cell_a = row[0].value
        cell_b = row[1].value if len(row) > 1 else None
        if cell_a is not None and str(cell_a).strip().lower() == "report summary":
            summary_started = True
            continue
        if summary_started and cell_a is not None:
            label = str(cell_a).strip()
            summary[label.lower()] = cell_b

    if not summary_started:
        return {"pass": False, "score": 0.0, "feedback": "Could not find 'Report Summary' header row in the Priya Natarajan worksheet."}

    feedback_parts = []
    checks_passed = 0
    total_checks = 6

    def get_val(key_variants):
        for k in key_variants:
            if k.lower() in summary:
                return summary[k.lower()]
        return None

    def parse_number(val):
        """Try to extract a numeric value from val."""
        if val is None:
            return None
        if isinstance(val, (int, float)):
            return float(val)
        s = str(val).strip()
        # Remove currency symbols, commas, spaces, dollar word
        s = re.sub(r'[\$,€£]', '', s)
        s = s.strip()
        try:
            return float(s)
        except ValueError:
            return None

    # 1. Jira Key
    jira_val = get_val(["Jira Key", "jira key", "JIRA Key"])
    if jira_val is not None and str(jira_val).strip().lower() == "ops-39":
        checks_passed += 1
        feedback_parts.append(f"PASS Jira Key: found '{jira_val}'")
    else:
        feedback_parts.append(f"FAIL Jira Key: expected 'OPS-39', found '{jira_val}'")

    # 2. Total Approved == 0
